const P=[["Clinic booking platform","Online booking, reminders and payments for 400 clinics. Next.js front end with a Node API.",["React","Node","Postgres"],"1551288049-bebda4e38f71"],["Parcel tracking app","Live delivery tracking with maps and push updates for 2 million monthly users.",["React","Node"],"1558494949-ef010cbdcc31"],["Price forecasting tool","A Python service that predicts demand for a grocery chain, with a simple dashboard.",["Python","FastAPI"],"1504868584819-f8e8b4b6d7e3"],["Open-source form library","A tiny, accessible form library for React with 3,400 stars on GitHub.",["React","TypeScript"],"1555066931-4365d14bab8c"]];
const $=id=>document.getElementById(id);
function proj(t){$('proj').innerHTML=P.filter(p=>t==='all'||p[2].includes(t)||(t==='Python'&&p[2].includes('Python'))).map(p=>`<article class="pj"><img src="https://images.unsplash.com/photo-${p[3]}?w=700&h=394&q=75&auto=format&fit=crop" alt="Screenshot for ${p[0]}" width="700" height="394" loading="lazy"><div class="bd"><h3>${p[0]}</h3><p>${p[1]}</p><div class="tags">${p[2].map(x=>`<span>${x}</span>`).join('')}</div><div class="lk"><a href="#">Live site</a><a href="#">Source code</a></div></div></article>`).join('')}
$('chips').onclick=e=>{const b=e.target.closest('button');if(!b)return;$('chips').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));proj(b.dataset.t)};proj('all');
let h='';for(let i=0;i<364;i++){const v=Math.abs(Math.sin(i*1.37)+Math.cos(i*.21))*2.2,wk=i%7>4?0.4:1,l=Math.min(4,Math.floor(v*wk));h+=`<i class="${l?'l'+l:''}"></i>`}$('hm').innerHTML=h;
$('cp').onclick=()=>{navigator.clipboard&&navigator.clipboard.writeText($('em').textContent);$('cp').textContent='Copied ✓';setTimeout(()=>$('cp').textContent='Copy email',1800)};
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
